#!/usr/bin/env bash
# Reproduce the hand-written ngspice compact-model anchor study.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ngspice="${RSPICE_BENCH_NGSPICE:-}"
samples="${RSPICE_BENCH_SAMPLES:-7}"
timestamp="$(date -u +%Y%m%dT%H%M%SZ)"
out="${1:-$here/../../../results/external-device-stamp-${timestamp}-$$.json}"

if [[ -z "$ngspice" ]]; then
  echo "RSPICE_BENCH_NGSPICE is not set; select an ngspice release executable" >&2
  exit 2
fi
if [[ ! -x "$ngspice" ]]; then
  echo "not executable: $ngspice" >&2
  exit 2
fi
if [[ ! "$samples" =~ ^[1-9][0-9]*$ ]]; then
  echo "RSPICE_BENCH_SAMPLES must be a positive integer, got: $samples" >&2
  exit 2
fi
if [[ -e "$out" ]]; then
  echo "refusing to overwrite immutable result: $out" >&2
  exit 2
fi

DEVICES=200
SWEEP_POINTS=200
work="$(mktemp -d "${TMPDIR:-/tmp}/rspice-device-anchor.XXXXXX")"
report_tmp=""
cleanup() {
  rm -rf -- "$work"
  if [[ -n "$report_tmp" && -e "$report_tmp" ]]; then
    rm -f -- "$report_tmp"
  fi
}
trap cleanup EXIT

json_escape() {
  printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

emit_vbic() {
  local mode="$1" path="$2"
  {
    echo "* VBIC anchor ($mode): $DEVICES devices, generated by run.sh"
    echo ".options acct"
    echo "vb 1 0 dc 0.8"
    echo "vc 2 0 dc 2.0"
    for ((i = 1; i <= DEVICES; i++)); do
      if [[ "$mode" == loaded ]]; then
        echo "q$i 2 1 0 qmod"
      else
        echo "r$i 2 1 1meg"
      fi
    done
    echo ".model qmod npn level=4"
    echo ".dc vb 0.5 0.9 $(awk -v p="$SWEEP_POINTS" 'BEGIN{printf "%.6f", 0.4/p}')"
    echo ".print dc i(vc)"
    echo ".end"
  } > "$path"
}

emit_bsim4() {
  local mode="$1" path="$2"
  {
    echo "* BSIM4 anchor ($mode): $DEVICES devices, generated by run.sh"
    echo ".options acct"
    echo "vg 1 0 dc 1.0"
    echo "vd 2 0 dc 1.0"
    for ((i = 1; i <= DEVICES; i++)); do
      if [[ "$mode" == loaded ]]; then
        echo "m$i 2 1 0 0 nmod w=1u l=45n"
      else
        echo "r$i 2 1 1meg"
      fi
    done
    echo ".model nmod nmos level=14 version=4.8.2"
    echo ".dc vg 0.2 1.0 $(awk -v p="$SWEEP_POINTS" 'BEGIN{printf "%.6f", 0.8/p}')"
    echo ".print dc i(vd)"
    echo ".end"
  } > "$path"
}

verify_decks() {
  local name="$1" emit="$2"
  "$emit" loaded "$work/${name}_loaded.cir"
  "$emit" empty "$work/${name}_empty.cir"
  for mode in loaded empty; do
    if ! cmp -s "$work/${name}_${mode}.cir" "$here/${name}_${mode}.cir"; then
      echo "generated ${name}_${mode}.cir differs from the reviewed deck" >&2
      echo "update the generator and checked-in deck together in a reviewed change" >&2
      exit 1
    fi
  done
}

measure() {
  local deck="$1" log="$2"
  if ! "$ngspice" -b "$deck" > "$log" 2>&1; then
    echo "ngspice failed for $deck" >&2
    tail -20 "$log" >&2
    exit 1
  fi
  local load iters
  load="$(awk -F= '/Matrix load time/ {gsub(/ /,"",$2); print $2; exit}' "$log")"
  iters="$(awk -F= '/^Total iterations/ {gsub(/ /,"",$2); print $2; exit}' "$log")"
  if [[ -z "$load" || -z "$iters" || "$iters" == "0" ]]; then
    echo "required accounting fields are missing for $deck" >&2
    tail -20 "$log" >&2
    exit 1
  fi
  printf '%s %s\n' "$load" "$iters"
}

anchor_json() {
  local name="$1"
  local records=() normalized=()
  for ((sample = 1; sample <= samples; sample++)); do
    local loaded_load loaded_iters empty_load empty_iters ns
    read -r loaded_load loaded_iters <<<"$(measure "$work/${name}_loaded.cir" "$work/${name}-loaded-${sample}.log")"
    read -r empty_load empty_iters <<<"$(measure "$work/${name}_empty.cir" "$work/${name}-empty-${sample}.log")"
    ns="$(awk -v ll="$loaded_load" -v li="$loaded_iters" -v el="$empty_load" -v ei="$empty_iters" -v d="$DEVICES" 'BEGIN { printf "%.6f", (ll/li-el/ei)/d*1e9 }')"
    normalized+=("$ns")
    records+=("{\"loaded_load_seconds\":$loaded_load,\"loaded_iterations\":$loaded_iters,\"empty_load_seconds\":$empty_load,\"empty_iterations\":$empty_iters,\"ns_per_device_per_iteration\":$ns}")
  done
  local median
  median="$(printf '%s\n' "${normalized[@]}" | sort -n | awk '{v[NR]=$1} END {if (NR%2) printf "%.6f", v[(NR+1)/2]; else printf "%.6f", (v[NR/2]+v[NR/2+1])/2}')"
  printf '    {"model":"%s","devices":%d,"median_ns_per_device_per_iteration":%s,"samples":[' "$name" "$DEVICES" "$median"
  local separator=""
  for record in "${records[@]}"; do
    printf '%s%s' "$separator" "$record"
    separator=","
  done
  printf ']}'
}

verify_decks vbic emit_vbic
verify_decks bsim4 emit_bsim4

version="$($ngspice --version 2>&1 | awk '/Circuit level simulation/ {gsub(/^\*\* /,""); gsub(/\r/,""); print; exit}')"
if command -v sha256sum >/dev/null 2>&1; then
  executable_sha256="$(sha256sum "$ngspice" | awk '{print $1}')"
elif command -v shasum >/dev/null 2>&1; then
  executable_sha256="$(shasum -a 256 "$ngspice" | awk '{print $1}')"
else
  executable_sha256="unavailable"
fi
host="$(uname -a)"

mkdir -p "$(dirname "$out")"
report_tmp="$(mktemp "${out}.tmp.XXXXXX")"
{
  echo '{'
  echo '  "schema_version": 1,'
  echo '  "benchmark_id": "external-device-stamp",'
  printf '  "generated_at_utc": "%s",\n' "$(json_escape "$timestamp")"
  printf '  "host": "%s",\n' "$(json_escape "$host")"
  printf '  "ngspice_version": "%s",\n' "$(json_escape "$version")"
  printf '  "ngspice_executable_sha256": "%s",\n' "$executable_sha256"
  printf '  "sample_count": %d,\n' "$samples"
  echo '  "anchors": ['
  anchor_json vbic
  echo ','
  anchor_json bsim4
  echo
  echo '  ]'
  echo '}'
} > "$report_tmp"

# A hard link provides same-filesystem atomic no-clobber publication.
if ! ln "$report_tmp" "$out"; then
  echo "failed to publish immutable result: $out" >&2
  exit 1
fi
rm -f -- "$report_tmp"
report_tmp=""
echo "wrote $out"
cat "$out"
